package com.kuaixietech.aftersalesfunds;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.transaction.annotation.*;
import org.springframework.web.server.ResponseStatusException;
class AftersalesEscrowExecutionTest {
 @Test void budgetGetIsReadOnlyAndDoesNotAcquireFinancialLocks(){var f=new EscrowFixture();var result=f.service.budget("case");assertEquals("eligible",result.get("status"));assertEquals("200.00",result.get("requestedAmount"));assertTrue(f.writes.isEmpty());assertTrue(f.queries.stream().noneMatch(q->q.contains("FOR UPDATE")));verifyNoInteractions(f.money);}
 @Test void unprovableBudgetIsBlockedNotASuccessfulRefund(){var f=new EscrowFixture();f.order.put("status","completed");var result=f.service.budget("case");assertEquals("blocked",result.get("status"));assertFalse(result.containsKey("refundableGoods"));verifyNoInteractions(f.money);}
 @Test void onlyAdministratorCanExecuteFunds(){var f=new EscrowFixture();when(f.guard.requireAdmin()).thenThrow(new SecurityException());assertThrows(SecurityException.class,()->f.service.execute("case",f.input()));verifyNoInteractions(f.db,f.money);}
 @Test void staleDecisionCannotMoveWalletMoney(){var f=new EscrowFixture();assertThrows(ResponseStatusException.class,()->f.service.execute("case",new AftersalesEscrowFunds.Execute(f.input().requestId(),2,"stale")));verifyNoInteractions(f.money);assertTrue(f.writes.isEmpty());}
 @Test void partialRefundCreditsWalletAndReducesBothFrozenRepresentations(){var f=new EscrowFixture();var result=f.service.execute("case",f.input());assertEquals("succeeded",result.get("status"));assertEquals("escrow_wallet",result.get("refundMethod"));assertEquals("platform_wallet",result.get("destination"));assertFalse((Boolean)result.get("requiresAccounting"));verify(f.money).addBalance(eq("buyer"),eq(EscrowFixture.d("200")),eq("as_goods_refund"),eq("order"),any());assertEquals(EscrowFixture.d("870"),f.order.get("buyer_deposit"));assertEquals(EscrowFixture.d("870"),f.deposit.get("amount"));assertEquals(EscrowFixture.d("1000"),f.order.get("goods_amount"));assertEquals("consumed",f.reservation.get("stock_state"));assertEquals("resolved",f.after.get("status"));assertEquals("succeeded",f.after.get("refund_status"));assertTrue(f.writes.stream().noneMatch(q->q.contains("UPDATE t_products")||q.contains("t_currency_payments")));}
 @Test void sameRequestReturnsPostedCreditWithoutAnotherWalletTransfer(){var f=new EscrowFixture();var first=f.service.execute("case",f.input());var second=f.service.execute("case",f.input());assertEquals(first,second);verify(f.money,times(1)).addBalance(any(),any(),any(),any(),any());}
 @Test void sameCaseDifferentRequestCannotRefundTwice(){var f=new EscrowFixture();f.service.execute("case",f.input());assertThrows(ResponseStatusException.class,()->f.service.execute("case",new AftersalesEscrowFunds.Execute("223e4567-e89b-42d3-a456-426614174000",3,"second")));verify(f.money,times(1)).addBalance(any(),any(),any(),any(),any());}
 @Test void cumulativePartialRefundsRevalidateLedgerAndFrozenBudget(){var f=new EscrowFixture();f.service.execute("case",f.input());f.nextCase("case2","300");f.service.execute("case2",new AftersalesEscrowFunds.Execute("223e4567-e89b-42d3-a456-426614174000",3,"next decision"));assertEquals(EscrowFixture.d("570"),f.order.get("buyer_deposit"));assertEquals(EscrowFixture.d("500"),f.service.netGoods("order",EscrowFixture.d("1000")));assertEquals(2,f.executions.size());}
 @Test void refundCannotExceedRemainingGoodsEvenIfDecisionWasCorrupted(){var f=new EscrowFixture();f.service.execute("case",f.input());f.nextCase("case2","900");assertThrows(ResponseStatusException.class,()->f.service.execute("case2",new AftersalesEscrowFunds.Execute("223e4567-e89b-42d3-a456-426614174000",3,"over budget")));verify(f.money,times(1)).addBalance(any(),any(),any(),any(),any());}
 @Test void fullGoodsRefundLeavesFeesShippingAndVendorDepositForAccounting(){var f=new EscrowFixture();f.dispute.put("refund_amount",EscrowFixture.d("1000"));f.after.put("refund_amount",EscrowFixture.d("1000"));var first=f.service.execute("case",f.input());assertTrue((Boolean)first.get("requiresAccounting"));assertEquals("awaiting_accounting",f.dispute.get("stage"));assertEquals("awaiting_accounting",f.after.get("status"));assertEquals(EscrowFixture.d("70"),f.order.get("buyer_deposit"));assertEquals("frozen",f.order.get("vendor_deposit_status"));assertThrows(EscrowFundsProof.Blocked.class,()->f.service.netGoods("order",EscrowFixture.d("1000")));assertEquals(first,f.service.execute("case",f.input()));verify(f.money,times(1)).addBalance(any(),any(),any(),any(),any());}
 @Test void currentRefundMarkerPreventsStaleEmptyHistoryFromPayingGross(){var f=new EscrowFixture();f.service.execute("case",f.input());f.executions.clear();var error=assertThrows(EscrowFundsProof.Blocked.class,()->f.service.netGoods("order",EscrowFixture.d("1000")));assertEquals("AS_ESCROW_REFUND_HISTORY_NOT_VISIBLE",error.getMessage());}
 @Test void missingLedgerReceiptCannotMarkCaseRefunded(){var f=new EscrowFixture();f.missingCreditLedger=true;assertThrows(IllegalStateException.class,()->f.service.execute("case",f.input()));assertTrue(f.executions.isEmpty());assertEquals("provider_unavailable",f.after.get("refund_status"));}
 @Test void failedFreezeCompareAndSetAbortsBeforeCaseCompletion(){var f=new EscrowFixture();f.failOrderWrite=true;assertThrows(IllegalStateException.class,()->f.service.execute("case",f.input()));assertTrue(f.executions.isEmpty());assertEquals("awaiting_refund",f.dispute.get("stage"));}
 @Test void executeDeclaresOneReadCommittedTransactionForBalanceAndProof()throws Exception{var tx=AftersalesEscrowFunds.class.getMethod("execute",String.class,AftersalesEscrowFunds.Execute.class).getAnnotation(Transactional.class);assertNotNull(tx);assertEquals(Isolation.READ_COMMITTED,tx.isolation());}
 @Test void ownHistoryAndEventsExposeNoOperatorOrSourceSnapshot(){var f=new EscrowFixture();var result=f.service.execute("case",f.input());var history=f.service.mine(20,0);assertFalse(history.getFirst().containsKey("operator_id"));assertFalse(history.getFirst().containsKey("source_snapshot"));var events=f.service.events(result.get("id").toString(),false,50,0);assertFalse(events.getFirst().containsKey("actor_id"));when(f.guard.requireActiveProfile()).thenReturn("other");assertThrows(ResponseStatusException.class,()->f.service.events(result.get("id").toString(),false,50,0));}
}
